const initializeWamGroup=(groupId,groupKey)=>{const audioWorkletGlobalScope=globalThis;class WamGroup{constructor(groupId,groupKey){this._groupId=groupId;this._validate=key=>key==groupKey;this._processors=new Map;this._eventGraph=new Map}get groupId(){return this._groupId}get processors(){return this._processors}get eventGraph(){return this._eventGraph}validate(groupKey){return this._validate(groupKey)}addWam(wam){this._processors.set(wam.instanceId,wam)}removeWam(wam){if(this._eventGraph.has(wam))this._eventGraph.delete(wam);this._eventGraph.forEach(outputMap=>{outputMap.forEach(set=>{if(set&&set.has(wam))set.delete(wam)})});this._processors.delete(wam.instanceId)}connectEvents(fromId,toId,output){const from=this._processors.get(fromId);const to=this._processors.get(toId);let outputMap;if(this._eventGraph.has(from)){outputMap=this._eventGraph.get(from)}else{outputMap=[];this._eventGraph.set(from,outputMap)}if(outputMap[output]){outputMap[output].add(to)}else{const set=new Set;set.add(to);outputMap[output]=set}}disconnectEvents(fromId,toId,output){const from=this._processors.get(fromId);if(!this._eventGraph.has(from))return;const outputMap=this._eventGraph.get(from);if(typeof toId==="undefined"){outputMap.forEach(set=>{if(set)set.clear()});return}const to=this._processors.get(toId);if(typeof output==="undefined"){outputMap.forEach(set=>{if(set)set.delete(to)});return}if(!outputMap[output])return;outputMap[output].delete(to)}emitEvents(from,...events){if(!this._eventGraph.has(from))return;const downstream=this._eventGraph.get(from);downstream.forEach(set=>{if(set)set.forEach(wam=>wam.scheduleEvents(...events))})}}if(audioWorkletGlobalScope.AudioWorkletProcessor){audioWorkletGlobalScope.webAudioModules.addGroup(new WamGroup(groupId,groupKey))}};export default initializeWamGroup;